INSERT INTO `recipe_steps` VALUES (1, '鸡胸肉切块，少量盐和黑胡椒腌制。蔬菜洗净切好。', 10, '准备食材', 0);
INSERT INTO `recipe_steps` VALUES (1, '平底锅少油，鸡胸肉煎至两面金黄熟透。', 6, '煎鸡胸肉', 1);
INSERT INTO `recipe_steps` VALUES (1, '将蔬菜与鸡胸肉混合，淋橄榄油与柠檬汁拌匀。', 3, '混合装盘', 2);
INSERT INTO `recipe_steps` VALUES (2, '把熟藜麦铺底。', 2, '装碗', 0);
INSERT INTO `recipe_steps` VALUES (2, '香蕉切片，加入蓝莓。', 3, '加水果', 1);
INSERT INTO `recipe_steps` VALUES (2, '加入核桃与无糖酸奶，拌匀或分区摆放。', 3, '加坚果酸奶', 2);
INSERT INTO `recipe_steps` VALUES (3, '烤箱预热 200℃，三文鱼抹少量橄榄油与黑胡椒。', 5, '预热与准备', 0);
INSERT INTO `recipe_steps` VALUES (3, '三文鱼与蔬菜同盘烤制，至熟透。', 12, '烤制', 1);
INSERT INTO `recipe_steps` VALUES (3, '出炉挤柠檬汁，按口味少量盐或不加盐。', 2, '调味', 2);
INSERT INTO `recipe_steps` VALUES (4, '将菠菜、香蕉、牛油果与无糖豆浆打至顺滑。', 3, '打碎', 0);
INSERT INTO `recipe_steps` VALUES (4, '倒入碗中，撒奇亚籽或少量坚果。', 2, '装碗点缀', 1);
INSERT INTO `recipe_steps` VALUES (5, '番茄切块，小火炒出汁。', 4, '炒番茄', 0);
INSERT INTO `recipe_steps` VALUES (5, '加水煮开后下虾仁至变色。', 6, '加水煮', 1);
INSERT INTO `recipe_steps` VALUES (5, '慢慢倒入蛋液形成蛋花，少量盐或不放。', 3, '打蛋花', 2);
INSERT INTO `recipe_steps` VALUES (6, '杯底铺燕麦，再加酸奶。', 3, '分层装杯', 0);
INSERT INTO `recipe_steps` VALUES (6, '加蓝莓与坚果碎，冷藏或即食。', 3, '加莓果坚果', 1);
INSERT INTO `recipes` VALUES (1, 320, 18, '2026-01-18 00:15:01.447479', '高蛋白搭配足量蔬菜，饱腹感更强，热量更可控。', 12, 8, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 1, 'intestine,pancreas,heart', 35, 90, 'high_protein,high_fiber,low_carb,low_salt', 15, '鸡胸肉水果蔬菜沙拉', '2026-01-18 00:15:01.447479', '');
