INSERT INTO `recipes` VALUES (5, 260, 10, '2026-01-18 00:15:01.522254', '清淡易消化，补蛋白同时控制盐分。', 12, 3, 'https://images.unsplash.com/photo-1604909053197-45c574b3c0c9?auto=format&fit=crop&w=800&q=80', 1, 'stomach,heart,kidney', 24, 60, 'low_salt,high_protein', 15, '番茄鸡蛋虾仁汤', '2026-01-18 00:15:01.522254', '');
